import React, { useEffect, useState } from 'react';
import { getProfile, updateProfile } from '../services/api';

const Profile = () => {
  const [profile, setProfile] = useState({});
  const [editing, setEditing] = useState(false);
  const [error, setError] = useState('');

  const token = localStorage.getItem('auth_token');

  useEffect(() => {
    const load = async () => {
      if (!token) return;
      try {
        const res = await getProfile(token);
        setProfile(res.data.profile || {});
      } catch (e) {
        setError('Unable to load profile');
      }
    };
    load();
  }, [token]);

  const handleSave = async () => {
    try {
      const res = await updateProfile(token, profile);
      setProfile(res.data.profile);
      setEditing(false);
    } catch (e) {
      setError('Unable to update profile');
    }
  };

  return (
    <div className="p-8">
      <h2 className="text-xl font-semibold mb-4">Profile</h2>
      {error && <div className="text-sm text-red-600 mb-2">{error}</div>}
      <div className="bg-white p-6 rounded shadow max-w-xl">
        <label className="block text-sm">Full name</label>
        <input value={profile.fullname || ''} onChange={e => setProfile({...profile, fullname: e.target.value})} className="w-full border p-2 rounded mb-3" disabled={!editing} />
        <label className="block text-sm">Email</label>
        <input value={profile.email || ''} onChange={e => setProfile({...profile, email: e.target.value})} className="w-full border p-2 rounded mb-3" disabled={!editing} />
        <div className="flex gap-2">
          {!editing ? (
            <button onClick={() => setEditing(true)} className="px-4 py-2 bg-primary text-white rounded">Edit</button>
          ) : (
            <>
              <button onClick={handleSave} className="px-4 py-2 bg-primary text-white rounded">Save</button>
              <button onClick={() => setEditing(false)} className="px-4 py-2 border rounded">Cancel</button>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default Profile;
